from pathlib import Path

p=Path('app/src/main/assets/www/core/major-project-service.js')
s=p.read_text()

helper="function findAsset(f,assetId){if(Array.isArray(f?.assets))return f.assets.find(a=>String(a?.assetId??a?.id)===String(assetId))??null;if(f?.assets&&typeof f.assets==='object')return f.assets[assetId]??Object.values(f.assets).find(a=>String(a?.assetId??a?.id)===String(assetId))??null;return null;}"
extra=helper+"\nfunction findBase(f,baseId){if(Array.isArray(f?.basesOfInfluence))return f.basesOfInfluence.find(b=>String(b?.baseId??b?.id)===String(baseId))??null;if(f?.basesOfInfluence&&typeof f.basesOfInfluence==='object')return f.basesOfInfluence[baseId]??Object.values(f.basesOfInfluence).find(b=>String(b?.baseId??b?.id)===String(baseId))??null;return null;}\nfunction locationOf(v){return v?.location??v?.locationId??null;}\nfunction sameLocation(a,b){return a!=null&&b!=null&&canonicalJson(a)===canonicalJson(b);}" 
if 'function findBase(' not in s:
    s=s.replace(helper,extra,1)

start=s.index(' extremeFactionAid({')
end=s.index('\n complete({',start)
new_extreme=""" extremeFactionAid({campaignId,projectId,factionId,contributorId=null,assetId=null,hitPointsCommitted,physicalDice}){const {loaded,state}=load(this.persistence,campaignId);if(!state)return Object.freeze({status:loaded.status});const p=projects(state)[projectId],f=faction(state,factionId);if(!p||p.status!=='ACTIVE')return Object.freeze({status:'ACTIVE_PROJECT_NOT_FOUND_NO_MUTATION',revision:loaded.revision});if(!f)return Object.freeze({status:'FACTION_NOT_FOUND_NO_MUTATION',revision:loaded.revision});const id=String(contributorId??assetId??'');if(!id)return Object.freeze({status:'FACTION_CONTRIBUTOR_ID_REQUIRED_NO_MUTATION',revision:loaded.revision});const projectLocation=p.gmContract?.location??p.location??null;if(projectLocation==null)return Object.freeze({status:'EXPLICIT_CONTEXT_CONTRACT_NO_MUTATION',revision:loaded.revision,contextRequired:['MAJOR_PROJECT_LOCATION_EVIDENCE']});const asset=findAsset(f,id),base=findBase(f,id),contributor=asset??base;if(!contributor)return Object.freeze({status:'FACTION_ASSET_OR_BASE_NOT_FOUND_NO_MUTATION',revision:loaded.revision});if(!sameLocation(locationOf(contributor),projectLocation))return Object.freeze({status:'FACTION_CONTRIBUTOR_NOT_AT_PROJECT_LOCATION_NO_MUTATION',revision:loaded.revision,projectLocation,contributorLocation:locationOf(contributor)});if(!Number.isInteger(hitPointsCommitted)||hitPointsCommitted<1||!Number.isInteger(contributor.hp)||contributor.hp<hitPointsCommitted)return Object.freeze({status:'INVALID_CONTRIBUTOR_HP_COMMITMENT_NO_MUTATION',revision:loaded.revision});const extraDamage=physicalD4(physicalDice),next=clone(state),np=next.worldState.majorProjects[projectId],nf=next.factionState[factionId],nc=asset?findAsset(nf,id):findBase(nf,id);nc.hp=Math.max(0,nc.hp-hitPointsCommitted-extraDamage);const before=np.currentDifficulty;np.currentDifficulty=Math.max(1,np.currentDifficulty-hitPointsCommitted);const contributorKind=asset?'ASSET':'BASE_OF_INFLUENCE';np.history=[...(np.history??[]),{kind:'FACTION_EXTREME_AID',factionId,contributorId:id,contributorKind,hitPointsCommitted,extraDamage,difficultyReduction:before-np.currentDifficulty,revision:loaded.revision+1}];const c=commit({persistence:this.persistence,loaded,next,campaignId,kind:'MAJOR_PROJECT_FACTION_EXTREME_AID',suffix:`project:${projectId}:extreme:${id}`,payload:{projectId,factionId,contributorId:id,contributorKind,hitPointsCommitted,extraDamage,difficultyBefore:before,difficultyAfter:np.currentDifficulty,contributorHpAfter:nc.hp,projectLocation}});return Object.freeze({status:c.receipt.status,receipt:c.receipt,extraDamage,contributorKind,contributorHpAfter:nc.hp,project:c.receipt.status==='OK'?clone(np):null});}"""
s=s[:start]+new_extreme+s[end:]

old="if(!gmOutcome||typeof gmOutcome!=='object'||!String(gmOutcome.summary??'').trim())return Object.freeze({status:'GM_OUTCOME_REQUIRED_NO_MUTATION',revision:loaded.revision,readiness});const next=clone(state)"
new="if(!gmOutcome||typeof gmOutcome!=='object'||!String(gmOutcome.summary??'').trim())return Object.freeze({status:'GM_OUTCOME_REQUIRED_NO_MUTATION',revision:loaded.revision,readiness});if(p.gmContract?.magicalProject===true){const required=Number(p.gmContract?.workingCountRequired);if(!Number.isInteger(required)||required<1||required>3)return Object.freeze({status:'EXPLICIT_CONTEXT_CONTRACT_NO_MUTATION',revision:loaded.revision,contextRequired:['GM_ASSIGNS_MAGICAL_PROJECT_WORKING_COUNT_1_TO_3'],readiness});const evidence=Array.isArray(gmOutcome.workingEvidence)?gmOutcome.workingEvidence:[];if(evidence.length<required||evidence.slice(0,required).some(w=>w?.verifiedAppropriateDegreeAndScope!==true))return Object.freeze({status:'MAGICAL_PROJECT_WORKING_EVIDENCE_REQUIRED_NO_MUTATION',revision:loaded.revision,requiredWorkingCount:required,received:evidence.length,contextRequired:['WORKING_EXISTS','GM_VERIFIES_APPROPRIATE_DEGREE_AND_SCOPE'],readiness});}const next=clone(state)"
if old not in s: raise SystemExit('complete marker not found')
s=s.replace(old,new,1)

p.write_text(s)
